-- Vai trò và quyền: mỗi tài khoản một vai trò (user.role_id), quyền lưu ở role_permission,
-- phạm vi dữ liệu (all / own) lưu ở role.scopes. Giữ cột user.role cho tới migration 010.

CREATE TABLE IF NOT EXISTS "role" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(30),
  "name" varchar(100) NOT NULL,
  "description" varchar(500),
  "scopes" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "created_by" INTEGER,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "role_code_uq" ON "role" ("code") WHERE "code" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "role_name_uq" ON "role" (lower("name"));
DROP TRIGGER IF EXISTS "role_updated_at" ON "role";
CREATE TRIGGER "role_updated_at" BEFORE UPDATE ON "role" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE IF NOT EXISTS "role_permission" (
  "role_id" INTEGER NOT NULL REFERENCES "role"("id") ON DELETE CASCADE,
  "permission" varchar(60) NOT NULL,
  PRIMARY KEY ("role_id", "permission")
);

ALTER TABLE "user" ADD COLUMN IF NOT EXISTS "role_id" INTEGER REFERENCES "role"("id") ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS "user_role_id" ON "user" ("role_id");

INSERT INTO "role" ("code", "name", "description")
VALUES ('admin', 'Quản trị viên', 'Luôn có mọi quyền')
ON CONFLICT DO NOTHING;

-- Chuyển tài khoản cũ.
UPDATE "user" SET "role_id" = (SELECT "id" FROM "role" WHERE "code" = 'admin')
WHERE "role" = 'admin' AND "role_id" IS NULL;

-- operator / reviewer / manning_agent: Chưa có vai trò (role_id để NULL).
UPDATE "user" SET "role_id" = NULL
WHERE "role" IN ('operator', 'reviewer', 'manning_agent') AND "role_id" IS NOT NULL;

-- training_center / seafarer không còn đăng nhập: xoá mềm.
UPDATE "user" SET "deleted_at" = NOW(), "is_active" = 0
WHERE "role" IN ('training_center', 'seafarer') AND "deleted_at" IS NULL;
